//! Admit an activation's generated product sources before lexical analysis.
//! Package ownership, logical-path collisions and source-instance coordinates
//! belong here; no syntax or semantic work is performed during admission.

use diagnostics::Diagnostic;
use std::collections::{HashMap, HashSet};
use std::path::Path;
use std::sync::Arc;

/// The immutable source frontier and exact generated bytes that extended it.
/// Source assembly consumes this through `parse`, retaining each custody row
/// as a separate syntax forest so pre-resolution normalization cannot synthesize
/// across generated-unit boundaries.
pub struct GeneratedSourceExtension {
    sources: Arc<source::SourceMap>,
    custody: Vec<(source::SourceId, build_output::PackageGeneratedSource)>,
    base_sources: Arc<source::SourceMap>,
}

impl GeneratedSourceExtension {
    pub fn custody(&self) -> &[(source::SourceId, build_output::PackageGeneratedSource)] {
        &self.custody
    }

    pub(crate) fn into_source_inputs(
        self,
        base_sources: &Arc<source::SourceMap>,
    ) -> Result<
        (
            Arc<source::SourceMap>,
            Vec<(source::SourceId, build_output::PackageGeneratedSource)>,
        ),
        Vec<Diagnostic>,
    > {
        if !Arc::ptr_eq(base_sources, &self.base_sources) {
            return Err(vec![Diagnostic::error(
                "retained generated-source extension no longer matches its base source frontier",
            )]);
        }
        Ok((self.sources, self.custody))
    }
}

pub fn admit_generated_extension(
    base_sources: &Arc<source::SourceMap>,
    package_root: &Path,
    package_identity: Option<semantic_vocabulary::PackageKeyIdentity>,
    generated_sources: &[build_output::PackageGeneratedSource],
) -> Result<GeneratedSourceExtension, Vec<Diagnostic>> {
    let mut sources = (**base_sources).clone();
    let mut retained = Vec::with_capacity(generated_sources.len());
    // Included paths have already been validated by staged-output custody.
    // Retain their owners while collision checks borrow generated paths.
    let logical_paths = generated_sources
        .iter()
        .map(|generated| {
            let mut logical_path = package_root.join(".omega/generated");
            for component in generated.relative_path().split(|byte| *byte == b'/') {
                logical_path.push(
                    std::str::from_utf8(component)
                        .expect("validated generated source paths retain UTF-8 components"),
                );
            }
            logical_path
        })
        .collect::<Vec<_>>();
    let collisions = match logical_paths.as_slice() {
        [] => Vec::new(),
        [logical_path] => vec![
            base_sources
                .files()
                .any(|existing| existing.path == *logical_path),
        ],
        _ => {
            // Index only the requested extension, not every retained base file.
            // Later duplicates are already collisions; base matches need mark
            // only the first authored occurrence of each generated path.
            let mut generated_positions = HashMap::with_capacity(logical_paths.len());
            let mut collisions = vec![false; logical_paths.len()];
            for (position, logical_path) in logical_paths.iter().enumerate() {
                match generated_positions.entry(logical_path.as_path()) {
                    std::collections::hash_map::Entry::Vacant(entry) => {
                        entry.insert(position);
                    }
                    std::collections::hash_map::Entry::Occupied(_) => {
                        collisions[position] = true;
                    }
                }
            }
            for existing in base_sources.files() {
                if let Some(&position) = generated_positions.get(existing.path.as_path()) {
                    collisions[position] = true;
                }
            }
            collisions
        }
    };
    for ((generated, logical_path), collides) in
        generated_sources.iter().zip(logical_paths).zip(collisions)
    {
        let source = std::str::from_utf8(generated.bytes()).map_err(|_| {
            vec![Diagnostic::error(format!(
                "included generated source `{}` is not UTF-8 Omega source",
                String::from_utf8_lossy(generated.relative_path())
            ))]
        })?;
        if collides {
            return Err(vec![Diagnostic::error(format!(
                "generated source logical path `{}` collides with an existing source",
                logical_path.display()
            ))]);
        }

        let source_id = source::SourceId(sources.len());
        // Generated extension sources are the producing activation's
        // product-context handoff; they keep the base compilation's product
        // instance semantics rather than growing a second checked instance.
        let added = sources.add_checked_instance(
            logical_path.clone(),
            source,
            package_root.to_path_buf(),
            package_identity,
            source::SourceOrigin::User,
            source::SourceResolutionStratum::CurrentActivationExtension,
            source::DependencyScope::Product,
        );
        debug_assert_eq!(added.source_id, source_id);
        retained.push((source_id, generated.clone()));
    }
    Ok(GeneratedSourceExtension {
        sources: Arc::new(sources),
        custody: retained,
        base_sources: base_sources.clone(),
    })
}

/// One admitted dependency source instance. The same logical path may appear
/// in both scopes; package identity and bytes stay borrowed from its bundle.
pub(crate) struct DependencyGeneratedSource<'source> {
    pub logical_path: std::path::PathBuf,
    pub source: &'source build_output::PackageGeneratedSource,
    pub package: semantic_vocabulary::PackageKeyIdentity,
    pub scope: source::DependencyScope,
}

impl<'source> DependencyGeneratedSource<'source> {
    /// The authored base this generated unit resolves against: its package's
    /// project roots, exactly as the package's own compile seeds them, joined
    /// under the unit's checked instance. Generated source may select its
    /// package's admitted authored declarations (`wiki/spec/build/execution.md`,
    /// "Generated-source boundary"), so that base joins whether or not any
    /// consumer imports it. A consumer never loads a dependency's `build.omg`.
    pub fn authored_base(
        &self,
        package_inputs: &crate::PackageCompilationInputs,
    ) -> Result<Vec<(std::path::PathBuf, source::DependencyScope)>, Vec<Diagnostic>> {
        let filesystem = package_inputs.source_filesystem();
        let package_root = package_inputs
            .package_root(self.package)
            .expect("validated generated-source bundle retains its package root");
        let roots = super::project_roots(package_root, filesystem);
        roots
            .sources
            .iter()
            .filter(|path| Some(*path) != roots.build.as_ref() && filesystem.is_file(path))
            .map(|path| Ok((super::paths::normalize_path(path, filesystem)?, self.scope)))
            .collect()
    }

    /// Decode when this source reaches the load frontier, preserving authored
    /// diagnostic order relative to earlier source parsing and import errors.
    pub fn source_text(&self) -> Result<&'source str, Vec<Diagnostic>> {
        std::str::from_utf8(self.source.bytes()).map_err(|_| {
            vec![Diagnostic::error(format!(
                "included generated source `{}` is not UTF-8 Omega source",
                self.logical_path.display(),
            ))]
        })
    }
}

/// Admit the dependency bundle's ordered, scope-qualified paths before loading
/// any generated unit. Physical collisions and same-scope duplicates reject.
pub(crate) fn admit_dependency_generated_sources(
    package_inputs: &crate::PackageCompilationInputs,
    source_scope: source::DependencyScope,
) -> Result<Vec<DependencyGeneratedSource<'_>>, Vec<Diagnostic>> {
    let filesystem = package_inputs.source_filesystem();
    // A virtual path can name different bytes in the two checked scopes.
    // Route from the source graph to its exact activation bundle, not from a
    // package-wide 'build-only' classification. The acquisition remains shared.
    let mut entries = Vec::new();
    for (purpose, bundle) in package_inputs.dependency_generated_source_instances() {
        let scope = match purpose {
            build_declarations::DependencyPurpose::Product => source::DependencyScope::Product,
            build_declarations::DependencyPurpose::Build => source::DependencyScope::Build,
        };
        if source_scope == source::DependencyScope::Build && scope != source_scope {
            continue;
        }
        let package_root = package_inputs
            .package_root(bundle.package())
            .expect("validated generated-source bundle retains its package root");
        for source in bundle.sources() {
            // Keep path errors in authored order with physical collisions.
            entries.push((
                dependency_generated_source_logical_path(package_root, source),
                source,
                bundle.package(),
                scope,
            ));
        }
    }
    {
        let mut loaded_paths = HashSet::with_capacity(entries.len());
        for (logical_path, _, _, scope) in &entries {
            let logical_path = logical_path.as_ref().map_err(Clone::clone)?;
            if filesystem.exists(logical_path)
                || !loaded_paths.insert((logical_path.as_path(), *scope))
            {
                return Err(vec![Diagnostic::error(format!(
                    "generated dependency source logical path `{}` collides with another source",
                    logical_path.display(),
                ))]);
            }
        }
    }

    entries
        .into_iter()
        .map(|(logical_path, source, package, scope)| {
            Ok(DependencyGeneratedSource {
                logical_path: logical_path?,
                source,
                package,
                scope,
            })
        })
        .collect()
}

fn dependency_generated_source_logical_path(
    package_root: &Path,
    source: &build_output::PackageGeneratedSource,
) -> Result<std::path::PathBuf, Vec<Diagnostic>> {
    let mut logical_path = package_root.join(".omega/generated");
    for component in source.relative_path().split(|byte| *byte == b'/') {
        logical_path.push(std::str::from_utf8(component).map_err(|_| {
            vec![Diagnostic::error(
                "generated dependency source path is not canonical UTF-8",
            )]
        })?);
    }
    Ok(logical_path)
}
